// sync_fifo: parameterizable single-clock FIFO with first-word fall-through.
// Implements interface_spec.md and microarchitecture.md for
// requirement req-d57ae7630b.
`default_nettype none

module sync_fifo #(
    parameter DEPTH = 8,   // entries, 2 or more, any value
    parameter WIDTH = 8    // bits per entry, 1 or more
) (
    input  wire                       clk,
    input  wire                       rst_n,    // synchronous, active low
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam PW = $clog2(DEPTH);       // pointer width
    localparam CW = $clog2(DEPTH+1);     // count width, holds DEPTH itself
    localparam [PW-1:0] LAST    = DEPTH[PW-1:0] - 1'b1;  // DEPTH-1
    localparam [CW-1:0] DEPTH_C = DEPTH[CW-1:0];

    // Storage: datapath, not reset.
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    // State registers.
    reg [PW-1:0] wr_ptr;
    reg [PW-1:0] rd_ptr;
    reg [CW-1:0] count_q;

    // Next state.
    reg [PW-1:0] wr_ptr_n;
    reg [PW-1:0] rd_ptr_n;
    reg [CW-1:0] count_n;

    // Flags are compares on a register: no input-to-flag path.
    assign full  = (count_q == DEPTH_C);
    assign empty = (count_q == {CW{1'b0}});
    assign count = count_q;

    // Accepted requests: the flags gate the requests (overflow/underflow policy).
    wire wr_acc = wr_en && !full;
    wire rd_acc = rd_en && !empty;

    // First-word fall-through: combinational read of the oldest slot.
    assign rd_data = mem[rd_ptr];

    // Next-state logic.
    always @* begin
        wr_ptr_n = wr_ptr;
        rd_ptr_n = rd_ptr;
        count_n  = count_q;
        if (wr_acc) begin
            if (wr_ptr == LAST) wr_ptr_n = {PW{1'b0}};
            else                wr_ptr_n = wr_ptr + 1'b1;
        end
        if (rd_acc) begin
            if (rd_ptr == LAST) rd_ptr_n = {PW{1'b0}};
            else                rd_ptr_n = rd_ptr + 1'b1;
        end
        if (wr_acc && !rd_acc)      count_n = count_q + 1'b1;
        else if (rd_acc && !wr_acc) count_n = count_q - 1'b1;
    end

    // State registers with synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr  <= {PW{1'b0}};
            rd_ptr  <= {PW{1'b0}};
            count_q <= {CW{1'b0}};
        end else begin
            wr_ptr  <= wr_ptr_n;
            rd_ptr  <= rd_ptr_n;
            count_q <= count_n;
        end
    end

    // Storage write, only outside reset.
    always @(posedge clk) begin
        if (rst_n && wr_acc) mem[wr_ptr] <= wr_data;
    end

`ifdef FORMAL
    // Design-intent properties. Not run by this submission (no .sby).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) if (!f_past_valid) assume (!rst_n);

    (* anyconst *) reg [PW-1:0] f_addr;
    always @(*) assume (f_addr <= LAST);

    integer f_wdist;
    integer f_adist;
    reg     f_inuse;
    always @(*) begin
        if (wr_ptr >= rd_ptr) f_wdist = wr_ptr - rd_ptr;
        else                  f_wdist = DEPTH - rd_ptr + wr_ptr;
        if (f_addr >= rd_ptr) f_adist = f_addr - rd_ptr;
        else                  f_adist = DEPTH - rd_ptr + f_addr;
        f_inuse = (f_adist < count_q);
    end

    // The word last written to the chosen slot.
    reg [WIDTH-1:0] f_data;
    always @(posedge clk)
        if (rst_n && wr_acc && (wr_ptr == f_addr)) f_data <= wr_data;

    always @(*) begin
        if (f_past_valid) begin
            assert (full  == (count_q == DEPTH_C));
            assert (empty == (count_q == {CW{1'b0}}));
            assert (!(full && empty));
            assert (count_q <= DEPTH_C);
            assert (wr_ptr <= LAST);
            assert (rd_ptr <= LAST);
            if (full) assert (wr_ptr == rd_ptr);
            else      assert (f_wdist == count_q);
            if (f_inuse) assert (mem[f_addr] == f_data);
            if (f_inuse && (rd_ptr == f_addr)) assert (rd_data == f_data);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (count_q == {CW{1'b0}});
                assert (wr_ptr == {PW{1'b0}});
                assert (rd_ptr == {PW{1'b0}});
                assert (empty);
                assert (!full);
            end else begin
                case ({$past(wr_acc), $past(rd_acc)})
                    2'b10:   assert (count_q == $past(count_q) + 1'b1);
                    2'b01:   assert (count_q == $past(count_q) - 1'b1);
                    default: assert (count_q == $past(count_q));
                endcase
                if (!$past(wr_acc)) assert (wr_ptr == $past(wr_ptr));
                if (!$past(rd_acc)) assert (rd_ptr == $past(rd_ptr));
                if ($past(wr_en && full))  assert (wr_ptr == $past(wr_ptr));
                if ($past(rd_en && empty)) assert (rd_ptr == $past(rd_ptr));
            end
        end
    end

    reg f_was_full;
    always @(posedge clk) begin
        if (!rst_n)    f_was_full <= 1'b0;
        else if (full) f_was_full <= 1'b1;
    end

    always @(*) begin
        if (f_past_valid && rst_n) begin
            cover (full);
            cover (f_was_full && empty);
            cover (wr_acc && rd_acc);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
