// sync_fifo_tb: self-checking testbench for sync_fifo (interface_spec.md section 7).
// Two FIFOs on the same stimulus, DEPTH 8 x WIDTH 8 and DEPTH 5 x WIDTH 12,
// each checked every cycle against a reference queue.
`default_nettype none

// Reference-queue scoreboard for one FIFO instance (DEPTH <= 255).
module sync_fifo_sb #(
    parameter DEPTH = 8,
    parameter WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire                       rd_en,
    input  wire [WIDTH-1:0]           wr_data,
    input  wire                       full,
    input  wire                       empty,
    input  wire [$clog2(DEPTH+1)-1:0] count,
    input  wire [WIDTH-1:0]           rd_data,
    input  wire                       done,
    output wire [31:0]                n_pass,
    output wire [31:0]                n_fail,
    output wire                       reported
);
    localparam CW = $clog2(DEPTH+1);
    localparam PW = $clog2(DEPTH);
    localparam [7:0]    D8    = DEPTH[7:0];
    localparam [PW-1:0] LASTP = DEPTH[PW-1:0] - 1'b1;

    reg [WIDTH-1:0] q [0:255];
    reg [7:0]       head;
    reg [7:0]       tail;
    reg [7:0]       cnt_u;
    reg [7:0]       cnt_c;
    reg [PW-1:0]    wp;
    reg [PW-1:0]    rp;
    reg             known;
    reg             wacc;
    reg             racc;
    reg             rep;

    integer passed;
    integer failed;
    integer cov_fill, cov_wr_full, cov_drain, cov_rd_empty;
    integer cov_wr_rd_empty, cov_wr_rd_full, cov_wr_rd_mid;
    integer cov_wwrap, cov_rwrap, cov_rst_traffic;

    assign n_pass   = passed;
    assign n_fail   = failed;
    assign reported = rep;

`define SB_COVER(cnt, what) \
    if ((cnt) == 0) begin \
        $error("DEPTH %0d: coverage goal not reached: %s", DEPTH, what); \
        failed = failed + 1; \
    end else begin \
        passed = passed + 1; \
    end

    // Model update on each rising edge, from the pre-edge model state.
    initial begin
        known = 1'b0;
        head  = 8'd0;
        tail  = 8'd0;
        wp    = {PW{1'b0}};
        rp    = {PW{1'b0}};
        wacc  = 1'b0;
        racc  = 1'b0;
        cov_fill = 0;        cov_wr_full = 0;    cov_drain = 0;
        cov_rd_empty = 0;    cov_wr_rd_empty = 0; cov_wr_rd_full = 0;
        cov_wr_rd_mid = 0;   cov_wwrap = 0;      cov_rwrap = 0;
        cov_rst_traffic = 0;
        forever begin
            @(posedge clk);
            cnt_u = tail - head;
            if (rst_n === 1'b0) begin
                if ((known === 1'b1) && ((cnt_u != 8'd0) || wr_en || rd_en))
                    cov_rst_traffic = cov_rst_traffic + 1;
                head  = 8'd0;
                tail  = 8'd0;
                wp    = {PW{1'b0}};
                rp    = {PW{1'b0}};
                known = 1'b1;
            end else if (known === 1'b1) begin
                wacc = wr_en && (cnt_u != D8);
                racc = rd_en && (cnt_u != 8'd0);
                if (wr_en && (cnt_u == D8))   cov_wr_full  = cov_wr_full + 1;
                if (rd_en && (cnt_u == 8'd0)) cov_rd_empty = cov_rd_empty + 1;
                if (wr_en && rd_en) begin
                    if (cnt_u == 8'd0)    cov_wr_rd_empty = cov_wr_rd_empty + 1;
                    else if (cnt_u == D8) cov_wr_rd_full  = cov_wr_rd_full + 1;
                    else                  cov_wr_rd_mid   = cov_wr_rd_mid + 1;
                end
                if (racc) begin
                    head = head + 8'd1;
                    if (rp == LASTP) begin
                        rp = {PW{1'b0}};
                        cov_rwrap = cov_rwrap + 1;
                    end else begin
                        rp = rp + 1'b1;
                    end
                    if (!wacc && (cnt_u == 8'd1)) cov_drain = cov_drain + 1;
                end
                if (wacc) begin
                    q[tail] = wr_data;
                    tail = tail + 8'd1;
                    if (wp == LASTP) begin
                        wp = {PW{1'b0}};
                        cov_wwrap = cov_wwrap + 1;
                    end else begin
                        wp = wp + 1'b1;
                    end
                    if (!racc && (cnt_u == (D8 - 8'd1))) cov_fill = cov_fill + 1;
                end
            end
        end
    end

    // Output checks on each falling edge; final coverage report when done.
    initial begin
        passed = 0;
        failed = 0;
        rep    = 1'b0;
        forever begin
            @(negedge clk);
            if (known === 1'b1) begin
                cnt_c = tail - head;
                if (count !== cnt_c[CW-1:0]) begin
                    $error("DEPTH %0d: count is %0d, expected %0d", DEPTH, count, cnt_c);
                    failed = failed + 1;
                end else begin
                    passed = passed + 1;
                end
                if (full !== (cnt_c == D8)) begin
                    $error("DEPTH %0d: full is %b with %0d entries", DEPTH, full, cnt_c);
                    failed = failed + 1;
                end else begin
                    passed = passed + 1;
                end
                if (empty !== (cnt_c == 8'd0)) begin
                    $error("DEPTH %0d: empty is %b with %0d entries", DEPTH, empty, cnt_c);
                    failed = failed + 1;
                end else begin
                    passed = passed + 1;
                end
                if (cnt_c != 8'd0) begin
                    if (rd_data !== q[head]) begin
                        $error("DEPTH %0d: rd_data is %h, expected %h", DEPTH, rd_data, q[head]);
                        failed = failed + 1;
                    end else begin
                        passed = passed + 1;
                    end
                end
            end
            if ((done === 1'b1) && (rep === 1'b0)) begin
                `SB_COVER(cov_fill,        "fill to full")
                `SB_COVER(cov_wr_full,     "write while full")
                `SB_COVER(cov_drain,       "drain to empty")
                `SB_COVER(cov_rd_empty,    "read while empty")
                `SB_COVER(cov_wr_rd_empty, "write and read together when empty")
                `SB_COVER(cov_wr_rd_full,  "write and read together when full")
                `SB_COVER(cov_wr_rd_mid,   "write and read together in between")
                `SB_COVER(cov_wwrap,       "write pointer wrap")
                `SB_COVER(cov_rwrap,       "read pointer wrap")
                `SB_COVER(cov_rst_traffic, "reset during traffic")
                rep = 1'b1;
            end
        end
    end

`undef SB_COVER

endmodule

module sync_fifo_tb;
    reg         clk     = 1'b0;
    reg         rst_n   = 1'b0;
    reg         wr_en   = 1'b0;
    reg         rd_en   = 1'b0;
    reg  [11:0] wr_data = 12'd0;
    reg         done    = 1'b0;

    wire        full8, empty8, full5, empty5;
    wire [3:0]  count8;
    wire [2:0]  count5;
    wire [7:0]  rd8;
    wire [11:0] rd5;
    wire [31:0] pass8, fail8, pass5, fail5;
    wire        rep8, rep5;

    reg  [31:0]     rng_d;
    reg  [31:0]     rng_c;
    reg  [8*64-1:0] nonce;
    reg             b_rst, b_wr, b_rd;
    integer         i, ph, ok, total_pass, total_fail;

    always #5 clk = ~clk;

    sync_fifo #(.DEPTH(8), .WIDTH(8)) u_fifo8 (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .wr_data(wr_data[7:0]),
        .full(full8), .rd_en(rd_en), .rd_data(rd8), .empty(empty8), .count(count8)
    );

    sync_fifo #(.DEPTH(5), .WIDTH(12)) u_fifo5 (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .wr_data(wr_data),
        .full(full5), .rd_en(rd_en), .rd_data(rd5), .empty(empty5), .count(count5)
    );

    sync_fifo_sb #(.DEPTH(8), .WIDTH(8)) u_sb8 (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en), .wr_data(wr_data[7:0]),
        .full(full8), .empty(empty8), .count(count8), .rd_data(rd8),
        .done(done), .n_pass(pass8), .n_fail(fail8), .reported(rep8)
    );

    sync_fifo_sb #(.DEPTH(5), .WIDTH(12)) u_sb5 (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en), .wr_data(wr_data),
        .full(full5), .empty(empty5), .count(count5), .rd_data(rd5),
        .done(done), .n_pass(pass5), .n_fail(fail5), .reported(rep5)
    );

    // xorshift32: deterministic, simulator-independent stimulus.
    function [31:0] xs(input [31:0] x);
        reg [31:0] y;
        begin
            y  = x ^ (x << 13);
            y  = y ^ (y >> 17);
            y  = y ^ (y << 5);
            xs = y;
        end
    endfunction

    // Apply one cycle of stimulus on the falling edge.
    task drive(input r, input w, input rd);
        begin
            @(negedge clk);
            rng_d   = xs(rng_d);
            rst_n   = r;
            wr_en   = w;
            rd_en   = rd;
            wr_data = rng_d[11:0];
        end
    endtask

    initial begin
        rng_d = 32'h1234_5678;
        rng_c = 32'h9E37_79B9;

        // Reset, with requests asserted: they must be ignored.
        drive(1'b0, 1'b1, 1'b1);
        drive(1'b0, 1'b0, 1'b0);

        // Directed corner cases.
        drive(1'b1, 1'b0, 1'b1);            // read while empty: ignored
        drive(1'b1, 1'b1, 1'b1);            // together when empty: only the write
        drive(1'b1, 1'b0, 1'b1);            // drain to empty
        repeat (10) drive(1'b1, 1'b1, 1'b0); // fill both, then writes while full
        drive(1'b1, 1'b1, 1'b1);            // together when full: only the read
        repeat (4) drive(1'b1, 1'b1, 1'b1);  // together in between: count holds
        repeat (3) drive(1'b1, 1'b0, 1'b1);
        repeat (3) drive(1'b1, 1'b1, 1'b0);
        repeat (10) drive(1'b1, 1'b0, 1'b1); // drain, then reads while empty
        repeat (3) drive(1'b1, 1'b1, 1'b0);
        drive(1'b0, 1'b1, 1'b1);            // reset during traffic
        drive(1'b1, 1'b0, 1'b1);            // read right after reset: ignored
        repeat (12) drive(1'b1, 1'b1, 1'b0);
        drive(1'b0, 1'b0, 1'b0);            // reset while full
        drive(1'b1, 1'b0, 1'b0);

        // Random traffic: write-heavy, read-heavy and balanced phases, rare resets.
        for (i = 0; i < 3000; i = i + 1) begin
            rng_c = xs(rng_c);
            ph    = (i / 250) % 3;
            b_rst = (rng_c[23:16] != 8'd0);
            if (ph == 0) begin
                b_wr = (rng_c[3:0] < 4'd12);
                b_rd = (rng_c[7:4] < 4'd5);
            end else if (ph == 1) begin
                b_wr = (rng_c[3:0] < 4'd5);
                b_rd = (rng_c[7:4] < 4'd12);
            end else begin
                b_wr = rng_c[0];
                b_rd = rng_c[4];
            end
            drive(b_rst, b_wr, b_rd);
        end

        // Let the last requests settle and be checked.
        drive(1'b1, 1'b0, 1'b0);
        drive(1'b1, 1'b0, 1'b0);
        done = 1'b1;
        wait ((rep8 === 1'b1) && (rep5 === 1'b1));
        #1;

        total_pass = pass8 + pass5;
        total_fail = fail8 + fail5;

        nonce = {64{8'h00}};
        ok = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (ok == 0) $display("sync_fifo_tb: no nirmaan_nonce plusarg given");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, total_pass, total_fail);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
